let coachContractBusy=false;
function coachContract(c){return c.contract??={salary:Math.round((1+COACH_KEYS.reduce((s,k)=>s+c.attributes[k],0)/COACH_KEYS.length/30)*10)/10,through:Math.min(10000,state.year+1),revision:0,interim:false,startYear:state.year,baseline:{w:0,l:0,pw:0,pl:0}}}
function coachExtensionDemand(c){return Math.min(20,Math.ceil(Math.max(coachContract(c).salary*1.05,1+COACH_KEYS.reduce((s,k)=>s+c.attributes[k],0)/COACH_KEYS.length/25)*10)/10)}
function coachBuyout(c){const ct=coachContract(c);return Math.round(ct.salary*Math.max(0,ct.through-state.year+1-state.day/seasonLength())*100)/100}
function editableCoach(id,revision){if(Number(id)!==controlledTeamId()||!ownerCanManage())return null;const c=coachFor(team());return coachContract(c).revision===Number(revision)?c:null}
function coachContractPanel(club){const c=coachFor(club),ct=coachContract(c),own=club.id===controlledTeamId()&&ownerCanManage();return playerCard('Contract',`<dl class="pp-ledger"><div><dt>Annual salary</dt><dd>${money(ct.salary)}</dd></div><div><dt>Contract through</dt><dd>${ct.through}–${String(ct.through+1).slice(-2)}${ct.through<state.year?' · Expired':ct.interim?' · Interim':''}</dd></div><div><dt>Remaining buyout</dt><dd>${money(coachBuyout(c))}</dd></div></dl>${own?`<div class="actions"><button type="button" onclick="openCoachTermination(controlledTeamId(),${ct.revision})">Terminate Contract</button><button type="button" class="primary" onclick="openCoachExtension(controlledTeamId(),${ct.revision})">Negotiate extension</button></div>`:''}<p class="muted">Salary is covered by the coaching budget, with the contract salary as its minimum annual expense when budgets are enabled. Termination pays the remaining guaranteed salary immediately.</p>`)}
const coachDetailsBeforeContracts=coachProfileDetails;coachProfileDetails=function(club){return coachDetailsBeforeContracts(club)+coachContractPanel(club)};
function openCoachTermination(id,revision){const c=editableCoach(id,revision);if(!c||coachContractBusy)return;const assistant=[...c.assistants].sort((a,b)=>b.rating-a.rating)[0];titleModal('Terminate Contract',`<p>Terminate <strong>${escapeHTML(c.name)}</strong> and pay a <strong>${money(coachBuyout(c))}</strong> buyout?</p><p>${escapeHTML(assistant.name)}, your highest-rated assistant, will take over as interim head coach through the current season at $1.0M annually. The vacated assistant position will be filled automatically.</p><p>Cash after buyout: ${money(financeFor(team()).cash-coachBuyout(c))}. This does not use player salary-cap space.</p><div class="actions"><button type="button" onclick="openCoachProfile(controlledTeamId())">Cancel</button><button type="button" class="primary" onclick="terminateCoachContract(${revision})">Confirm termination</button></div>`)}
function openCoachExtension(id,revision){const c=editableCoach(id,revision);if(!c||coachContractBusy)return;const ct=coachContract(c),demand=coachExtensionDemand(c);titleModal('Negotiate extension',`<p>${escapeHTML(c.name)} is seeking at least <strong>${money(demand)} per season</strong>.</p><p>Added seasons follow the existing deal (through ${ct.through}). The new annual salary takes effect immediately. Player salary-cap space is unaffected.</p><form onsubmit="submitCoachExtension(event,${revision})"><div class="actions"><label>Annual salary ($M)<input name="salary" type="number" min="0.5" max="20" step="0.1" value="${demand}" required></label><label>Additional seasons<select name="years">${[1,2,3,4,5].map(n=>`<option value="${n}">${n}</option>`).join('')}</select></label></div><p id="coach-contract-feedback" role="status"></p><div class="actions"><button type="button" onclick="openCoachProfile(controlledTeamId())">Cancel</button><button type="submit" class="primary">Offer extension</button></div></form>`)}
async function commitCoachChange(change){if(coachContractBusy)return false;coachContractBusy=true;const before=copy(state);try{change();if(await save()===false){state=before;toast('Could not save the contract change. Please try again.');openCoachProfile(controlledTeamId());return false}render();openCoachProfile(controlledTeamId());return true}catch(error){state=before;toast(error.message);openCoachProfile(controlledTeamId());return false}finally{coachContractBusy=false}}
async function submitCoachExtension(event,revision){event.preventDefault();const c=editableCoach(controlledTeamId(),revision);if(!c||coachContractBusy)return false;const salary=Number(event.target.elements.salary.value),years=Number(event.target.elements.years.value),ct=coachContract(c),through=Math.max(state.year-1,ct.through)+years,feedback=document.getElementById('coach-contract-feedback');if(!Number.isFinite(salary)||salary<.5||salary>20||!Number.isInteger(years)||years<1||years>5||through>10000){feedback.textContent='Choose a salary from $0.5M–$20M and 1–5 additional seasons.';return false}if(salary+1e-9<coachExtensionDemand(c)){feedback.textContent=c.name+' declines. The requested minimum is '+money(coachExtensionDemand(c))+' per season.';return false}return commitCoachChange(()=>{ct.salary=Math.round(salary*10)/10;ct.through=through;ct.interim=false;ct.revision++;say('COACH EXTENSION: '+c.name+' agrees to '+years+' additional seasons through '+through+' at '+money(ct.salary)+' annually.');})}
async function terminateCoachContract(revision){const c=editableCoach(controlledTeamId(),revision);if(!c||coachContractBusy)return false;return commitCoachChange(()=>{const club=team(),cost=coachBuyout(c),ct=coachContract(c),assistant=[...c.assistants].sort((a,b)=>b.rating-a.rating)[0],replacement=generateCoach({...club,key:club.key+'-staff-'+ct.revision+'-'+state.year+'-'+state.day});financePost(financeFor(club),'operations',cost,true);financeSync(club);const base=coachSeasonRecord(club);replacement.name=assistant.name;replacement.age=38;replacement.attributes=Object.fromEntries(COACH_KEYS.map(k=>[k,Math.max(1,Math.min(99,assistant.rating-8))]));replacement.attributes[assistant.role==='Offense'?'offense':'defense']=assistant.rating;replacement.assistants=c.assistants.map(a=>a===assistant?replacement.assistants.find(q=>q.role===a.role):{...a});replacement.contract={salary:1,through:state.year,revision:ct.revision+1,interim:true,startYear:state.year,baseline:base};club.coach=replacement;say('COACH TERMINATION: '+c.name+' leaves '+club.city+'. Buyout '+money(cost)+'. '+replacement.name+' takes over as interim head coach.');})}
const coachReadBeforeContracts=readCoach;readCoach=function(raw,club,bad,year=2026){const c=coachReadBeforeContracts(raw,club,bad,year);if(raw?.contract!==undefined){const r=raw.contract;if(!r||!Number.isFinite(r.salary)||r.salary<.5||r.salary>20||!Number.isInteger(r.through)||r.through<1900||r.through>10000||!Number.isInteger(r.revision)||r.revision<0||r.revision>1000000||typeof r.interim!=='boolean'||!Number.isInteger(r.startYear)||r.startYear<1900||r.startYear>year)bad('invalid coach contract');c.contract={salary:r.salary,through:r.through,revision:r.revision,interim:r.interim,startYear:r.startYear,baseline:readCoachRecord(r.baseline,bad)}}return c};
const coachSnapshotBeforeContracts=coachSeasonSnapshot;coachSeasonSnapshot=function(club){const row=coachSnapshotBeforeContracts(club),ct=coachFor(club).contract;if(ct&&ct.startYear===state.year)for(const k of ['w','l','pw','pl'])row[k]=Math.max(0,row[k]-ct.baseline[k]);return row};
function coachBudgetExpense(f,club){return Math.max(f.budgets.coaching,coachContract(coachFor(club)).salary)}
